import{_ as t,o as a,c as s,aj as i}from"./chunks/framework.C6uXqnaX.js";const k=JSON.parse('{"title":"Updating the Component Class","description":"","frontmatter":{},"headers":[],"relativePath":"en/tutorials/learn-angular/2-updating-the-component-class.md","filePath":"en/tutorials/learn-angular/2-updating-the-component-class.md"}'),n={name:"en/tutorials/learn-angular/2-updating-the-component-class.md"};function p(o,e,l,h,c,r){return a(),s("div",null,e[0]||(e[0]=[i('<h1 id="updating-the-component-class" tabindex="-1">Updating the Component Class <a class="header-anchor" href="#updating-the-component-class" aria-label="Permalink to &quot;Updating the Component Class&quot;">​</a></h1><p>In Angular, the component&#39;s logic and behavior are defined in the component&#39;s TypeScript class.</p><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>Learn more about <a href="/en/essentials/templates#showing-dynamic-text">showing dynamic text in the essentials guide</a>.</p></div><p>In this activity, you&#39;ll learn how to update the component class and how to use <a href="/en/guide/templates/binding#render-dynamic-text-with-text-interpolation">interpolation</a>.</p><hr><h3 id="_1-add-a-property-called-city" tabindex="-1">1. Add a property called <code>city</code> <a class="header-anchor" href="#_1-add-a-property-called-city" aria-label="Permalink to &quot;1. Add a property called `city`&quot;">​</a></h3><p>Update the component class by adding a property called <code>city</code> to the <code>App</code> class.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> App</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  city</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;San Francisco&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The <code>city</code> property is of type <code>string</code> but you can omit the type because of <a href="https://www.typescriptlang.org/docs/handbook/type-inference.html" target="_blank" rel="noreferrer">type inference in TypeScript</a>. The <code>city</code> property can be used in the <code>App</code> class and can be referenced in the component template.</p><br><p>To use a class property in a template, you have to use the <code>{{ }}</code> syntax.</p><h3 id="_2-update-the-component-template" tabindex="-1">2. Update the component template <a class="header-anchor" href="#_2-update-the-component-template" aria-label="Permalink to &quot;2. Update the component template&quot;">​</a></h3><p>Update the <code>template</code> property to match the following HTML:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`Hello {{ city }}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre></div><p>This is an example of interpolation and is a part of Angular template syntax. It enables you to do much more than put dynamic text in a template. You can also use this syntax to call functions, write expressions and more.</p><h3 id="_3-more-practice-with-interpolation" tabindex="-1">3. More practice with interpolation <a class="header-anchor" href="#_3-more-practice-with-interpolation" aria-label="Permalink to &quot;3. More practice with interpolation&quot;">​</a></h3><p>Try this - add another set of <code>{{ }}</code> with the contents being <code>1 + 1</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`Hello {{ city }}, {{ 1 + 1 }}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre></div><p>Angular evaluates the contents of the <code>{{ }}</code> and renders the output in the template.</p><p>This is just the beginning of what&#39;s possible with Angular templates, keep on learning to find out more.</p>',20)]))}const u=t(n,[["render",p]]);export{k as __pageData,u as default};
